import {PALETTES,SCENES,EXAMPLE,validateDraft,randomFor,fitText} from './core.mjs';
const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',KEY='ce-foldnote-draft-v1';
let draft=validateDraft(EXAMPLE),art,busy=false;
const measureCanvas=document.createElement('canvas'),measure=measureCanvas.getContext('2d');
function say(text){$('status').textContent=text;}
function node(tag,attrs={},parent){const el=document.createElementNS(NS,tag);for(const[key,value]of Object.entries(attrs))el.setAttribute(key,String(value));if(parent)parent.append(el);return el;}
function textLine(parent,text,x,y,size,fill,family='Georgia, serif',extra={}){const t=node('text',{x,y,'font-size':size,fill,'font-family':family,...extra},parent);t.textContent=text;return t;}
function measureText(text,size,family='Georgia'){measure.font=size+'px '+family;return measure.measureText(text).width;}
function illustration(svg,p){const rand=randomFor(draft.seed),defs=node('defs',{},svg),clip=node('clipPath',{id:'sceneClip'},defs);node('rect',{x:60,y:65,width:880,height:440,rx:12},clip);const scene=node('g',{'clip-path':'url(#sceneClip)'},svg);node('rect',{x:60,y:65,width:880,height:440,fill:p.sky},scene);const sunX=240+rand()*480,sunY=175+rand()*55;
 if(draft.scene===0){node('circle',{cx:sunX,cy:sunY,r:77,fill:p.sun},scene);const a=300+rand()*60,b=330+rand()*70;node('path',{d:`M0 ${a} Q190 ${a-115} 470 ${b} T1050 ${a-25} V530H0Z`,fill:p.land},scene);node('path',{d:`M0 445 Q220 295 470 420 T1030 375 V530H0Z`,fill:p.front},scene);node('path',{d:'M380 530 Q590 445 555 360',fill:'none',stroke:p.paper,'stroke-width':18,opacity:.5},scene);}
 else if(draft.scene===1){node('circle',{cx:sunX,cy:sunY,r:64,fill:p.sun},scene);node('rect',{x:60,y:320,width:880,height:185,fill:p.land},scene);node('path',{d:'M40 395Q210 345 390 400T750 400T1040 395V530H40Z',fill:p.front},scene);for(let i=0;i<7;i++){const x=100+rand()*680,y=335+rand()*135;node('path',{d:`M${x} ${y} q25 -6 50 0`,fill:'none',stroke:p.paper,'stroke-width':3,opacity:.35},scene);}node('path',{d:'M40 485 Q250 438 430 488 T1000 465 V530H40Z',fill:p.sun,opacity:.65},scene);}
 else{node('rect',{x:60,y:65,width:880,height:440,fill:p.front},scene);for(let i=0;i<29;i++)node('circle',{cx:85+rand()*830,cy:90+rand()*270,r:1.5+rand()*2,fill:p.paper,opacity:.4+rand()*.5},scene);node('circle',{cx:sunX,cy:sunY,r:66,fill:p.sun},scene);node('circle',{cx:sunX+29,cy:sunY-21,r:60,fill:p.front},scene);node('path',{d:'M30 500 230 305 405 465 650 335 1000 505Z',fill:p.land},scene);node('path',{d:'M30 510 350 410 580 505 830 385 1000 505V530H30Z',fill:p.sky,opacity:.55},scene);}
}
function render(){const p=PALETTES[draft.palette];const svg=node('svg',{xmlns:NS,viewBox:'0 0 1000 1250',width:1000,height:1250,role:'img','aria-labelledby':'cardTitle cardDescription'});node('title',{id:'cardTitle'},svg).textContent='Your Foldnote postcard';node('desc',{id:'cardDescription'},svg).textContent=[draft.kicker,draft.title,draft.message,draft.signature].filter(Boolean).join('. ');node('rect',{width:1000,height:1250,fill:p.paper},svg);illustration(svg,p);
 textLine(svg,draft.kicker,500,559,17,p.muted,'Arial, sans-serif',{'text-anchor':'middle','letter-spacing':3});
 const title=fitText(draft.title,840,2,66,32,(t,s)=>measureText(t,s));title.lines.forEach((line,i)=>textLine(svg,line,500,640+i*(title.size*1.12),title.size,p.ink,'Georgia, serif',{'text-anchor':'middle'}));
 node('line',{x1:460,y1:785,x2:540,y2:785,stroke:p.sun,'stroke-width':2},svg);
 const body=fitText(draft.message,820,6,33,20,(t,s)=>measureText(t,s,'Arial'));const lineHeight=body.size*1.5;body.lines.forEach((line,i)=>textLine(svg,line,500,842+i*lineHeight,body.size,p.ink,'Arial, sans-serif',{'text-anchor':'middle'}));
 const sign=fitText(draft.signature,840,1,31,16,(t,s)=>measureText(t,s));textLine(svg,sign.lines.join(' '),500,1170,sign.size,p.muted,'Georgia, serif',{'text-anchor':'middle'});
 textLine(svg,'A NOTE WORTH KEEPING',500,1220,11,p.muted,'Arial, sans-serif',{'text-anchor':'middle','letter-spacing':3});
 $('preview').replaceChildren(svg);art=svg;document.querySelectorAll('[data-scene]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===draft.scene)));document.querySelectorAll('[data-palette]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===draft.palette)));$('paletteName').textContent=p.name;
 for(const[key,max]of[['kicker',32],['title',48],['message',220],['signature',40]])$(key+'Count').textContent=Array.from(draft[key]).length+' / '+max;
}
function populate(){for(const key of ['kicker','title','message','signature'])$(key).value=draft[key];render();}
const sceneIcons=['<path d="M1 13 6 6l5 7m-2 0 4-5 4 5M11 4h.01"/>','<path d="M1 11q4-4 8 0t8 0M1 15q4-4 8 0t8 0"/><circle cx="9" cy="4" r="2"/>','<path d="M12 2a6 6 0 1 0 4 9A6 6 0 0 1 12 2Z"/>'];
SCENES.forEach((name,i)=>{const b=document.createElement('button');b.className='scene';b.dataset.scene=i;b.innerHTML='<svg viewBox="0 0 18 18" class="icon" aria-hidden="true">'+sceneIcons[i]+'</svg>';b.append(document.createTextNode(name));b.addEventListener('click',()=>{draft.scene=i;render();say(name+' selected.');});$('scenes').append(b);});
PALETTES.forEach((p,i)=>{const b=document.createElement('button');b.className='swatch';b.dataset.palette=i;b.setAttribute('aria-label',p.name);const swatch=document.createElement('span');swatch.style.background='linear-gradient(135deg,'+p.sun+' 50%,'+p.front+' 50%)';b.append(swatch);b.addEventListener('click',()=>{draft.palette=i;render();say(p.name+' colours selected.');});$('palettes').insertBefore(b,$('paletteName'));});
for(const key of ['kicker','title','message','signature'])$(key).addEventListener('input',e=>{draft[key]=e.target.value;render();});
$('shuffle').addEventListener('click',()=>{draft.seed=(draft.seed+104729)>>>0;render();say('A fresh little landscape, with your words kept in place.');});
$('save').addEventListener('click',()=>{try{localStorage.setItem(KEY,JSON.stringify(validateDraft(draft)));$('load').disabled=false;say('Draft saved in this browser. Saving again replaces it.');}catch{say('This browser could not save the draft. You can still download your card.');}});
$('load').addEventListener('click',()=>{try{const raw=localStorage.getItem(KEY);if(!raw){$('load').disabled=true;say('There is no saved draft in this browser yet.');return;}draft=validateDraft(JSON.parse(raw));populate();say('Your saved draft is back.');}catch{say('That draft could not be loaded. Save a new draft to replace it.');}});
$('example').addEventListener('click',()=>{draft=validateDraft(EXAMPLE);populate();say('The example is back. Your saved draft is kept until you save again.');});
try{const raw=localStorage.getItem(KEY);if(raw)validateDraft(JSON.parse(raw));$('load').disabled=!raw;}catch{say('Saved drafts are unavailable in this browser. You can still make and download a card.');}
function svgString(){return new XMLSerializer().serializeToString(art);}
function download(blob,extension){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='foldnote-postcard.'+extension;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
$('svg').addEventListener('click',()=>{download(new Blob([svgString()],{type:'image/svg+xml;charset=utf-8'}),'svg');say('SVG download started. Keep it sharp at any size.');});
$('png').addEventListener('click',async()=>{if(busy)return;busy=true;$('png').disabled=true;$('svg').disabled=true;const source=new Blob([svgString()],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(source);let image;
 try{say('Making your picture…');image=await new Promise((resolve,reject)=>{const img=new Image(),timeout=setTimeout(()=>reject(Error('Image took too long')),10000);img.onload=()=>{clearTimeout(timeout);resolve(img);};img.onerror=()=>{clearTimeout(timeout);reject(Error('Image could not be rendered'));};img.src=url;});const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1500;const context=canvas.getContext('2d');if(!context)throw Error('Canvas unavailable');context.drawImage(image,0,0,1200,1500);const png=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('PNG unavailable')),'image/png'));download(png,'png');say('PNG download started. Your postcard is 1200 × 1500 pixels.');}catch{say('The picture could not be made here. Try Download SVG instead.');}finally{URL.revokeObjectURL(url);busy=false;$('png').disabled=false;$('svg').disabled=false;}
});
populate();
